    },
    {
      "card_ids": ["C03"],
      "claim": "Tiaprofenic acid, another benzoyl carboxylic acid NSAID, is almost completely absorbed with oral bioavailability about 90–100%, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "R-ketoprofen, the enantiomer of the closest analogue, showed absolute bioavailability of 84.5% in healthy subjects, reinforcing high F for this acidic NSAID class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an acidic NSAID with a benzoyl-pyrrolizine carboxylic acid structure. The closest experimental analogues, ketoprofen and tiaprofenic acid, are benzoyl carboxylic acid NSAIDs with absolute oral bioavailability ≥84–100% in humans. These direct, threshold-relevant measurements support high oral bioavailability (F ≥20%) for the query, despite low Morgan similarity scores.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule was retrieved; prediction relies on close analogues.",
    "Morgan similarity scores to the closest analogues are low (~0.27), limiting quantitative transferability.",
    "No query-specific data on first-pass metabolism, solubility, or formulation effects were available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

